// The demo fixtures (v3poc/fixtures, generated by build.py) and their step format.
import type { AssistantMessage, Control, Message, Session, WatchEvent, Workspace } from '@protocol/timeline'
import demoJson from '@fixtures/session-demo.json'
import workspaceJson from '@fixtures/workspace.json'

/** Fixture-only script steps; the semantics are documented at the top of v3poc/fixtures/build.py. */
export type ScriptStep =
  | { wait: number; event: WatchEvent }
  | { wait: number; stream: { message: AssistantMessage; cps: number; interval?: number } }
  | { wait: number; until: 'answer'; request_id: string }

export interface SessionFixture {
  account: { name: string; email: string }
  snapshot: Extract<WatchEvent, { type: 'snapshot' }>
  script: ScriptStep[]
  reply: ScriptStep[]
}

export const demo = demoJson as unknown as SessionFixture
export const workspace = workspaceJson as unknown as Workspace
export const DEMO_SESSION_ID = demo.snapshot.session.id

/** A small session for every other entry in the sidebar: the title as the question, one short answer. */
export function synthesizedFixture(id: string): SessionFixture {
  const s = workspace.sessions.find((x) => x.id === id)
  if (!s) throw new Error(`no session ${id}`)
  const device = workspace.devices.find((d) => d.id === s.device_id)
  const at = s.updated_at
  const session: Session = {
    id: s.id,
    title: s.title,
    agent: s.agent,
    device: { id: s.device_id, name: device?.name ?? s.device_id },
    cwd: s.cwd,
    created_at: at,
    updated_at: at,
    message_count: 2,
    config: demo.snapshot.session.config,
  }
  const messages: Message[] = [
    { id: `${id}-u0`, role: 'user', seq: 0, created_at: at, done: true, rewindable: true, parts: [{ type: 'text', text: s.title }] },
    {
      id: `${id}-a1`,
      role: 'assistant',
      turn_id: `${id}-u0`,
      seq: 1,
      created_at: at,
      done: true,
      parts: [
        {
          type: 'text',
          text: `这是「${s.title}」的演示会话，只有这一轮。\n\n完整的演示（思考、工具调用、计划、审批、流式输出）在 **修复已读后又变回未读** 这个会话里。`,
        },
      ],
    },
  ]
  const control: Control = {
    state: s.state === 'waiting' ? 'idle' : s.state,
    steer: 'native',
    pending: [],
    queued: [],
    usage: { used: 12_800, size: 200_000, updated_at: at },
    error: s.state === 'error' ? '上一轮失败了：Agent 进程退出（演示）' : undefined,
  }
  return {
    account: demo.account,
    snapshot: { type: 'snapshot', session, messages, has_more: false, control },
    script: [],
    reply: demo.reply,
  }
}

export function fixtureFor(id: string): SessionFixture {
  return id === DEMO_SESSION_ID ? demo : synthesizedFixture(id)
}
